from lt2http.util import (notify, dialog_ok, system_information, toUtf8,
                          getLocalizedString, getWindowsShortPath,
                          download_github_folder, read_current_version, write_current_version,
                          download_current_version, version_tuple, translatePath)

try:
    from ctypes import c_char_p, c_int, cdll
    ctypes_is_supported = True
except Exception as e:
    log.info("Cannot import ctypes: %s" % e)
    ctypes_is_supported = False

try:
    import subprocess
    hasSubprocess = True
    if not PLATFORM["fork"]:
        hasSubprocess = False
except:
    hasSubprocess = False

binary_platform = {}
repo = "ElementumOrg/lt2http-binaries"
config_path = os.path.join(translatePath("special://temp/"), "lt2http-config.json")
log_path = os.path.join(translatePath("special://temp/"), "lt2http.log")

# Address of the started lt2http: its port changes only on restart
lt2http_host = config.LT2HTTP_HOST

# Loaded shared library, reused on restarts as it cannot be unloaded safely
lib = None
last_lib = ""
last_exit_code = -1

def ensure_exec_perms(file_):
    st = os.stat(file_)
    os.chmod(file_, st.st_mode | stat.S_IEXEC)
    return file_

def android_get_current_appid():
    with open("/proc/%d/cmdline" % os.getpid()) as fp:
        return fp.read().rstrip("\0")

def get_lt2http_checksum(path):
    if not os.path.exists(path):
        return ""

    stats = os.stat(path)
    if stats.st_size < 40:
        return ""

    try:
        with open(path) as fp:
            fp.seek(0, os.SEEK_END)
            fp.seek(fp.tell() - 40, os.SEEK_SET)  # we put a sha1 there
            return fp.read().strip()
    except Exception as e:
        log.info("exception reading checksum path %s: %s" % (path, e))
        return ""

def is_writable(path):
    try:
        tempfile.TemporaryFile(dir=path).close()
    except Exception:
        return False
    return True


def get_lt2http_binary():
    global binary_platform
    binary_platform = get_platform()

    binary = "lt2http" + (binary_platform["os"] == "windows" and ".exe" or "")
    binary_dir = os.path.join(ADDON_PATH, "resources", "bin", "%(os)s-%(arch)s" % binary_platform)

    if binary_platform["os"] == "android":
        log.info("Detected binary folder: %s" % binary_dir)
        binary_dir_legacy = binary_dir.replace("/storage/emulated/0", "/storage/emulated/legacy")
        if os.path.exists(binary_dir_legacy):
            binary_dir = binary_dir_legacy
            log.info("Using changed binary folder for Android: %s" % binary_dir)

        app_id = android_get_current_appid()
        xbmc_data_path = os.path.join("/data", "data", app_id)
        if not os.path.exists(xbmc_data_path) or not is_writable(xbmc_data_path):
            log.info("%s path does not exist, so using %s as xbmc_data_path" % (xbmc_data_path, translatePath("special://xbmcbin/")))
            xbmc_data_path = translatePath("special://xbmcbin/")

        if not os.path.exists(xbmc_data_path) or not is_writable(xbmc_data_path):
            log.info("%s path does not exist, so using %s as xbmc_data_path" % (xbmc_data_path, translatePath("special://masterprofile/")))
            xbmc_data_path = translatePath("special://masterprofile/")

        dest_binary_dir = os.path.join(xbmc_data_path, "files", ADDON_ID, "bin", "%(os)s-%(arch)s" % binary_platform)
    else:
        try:
            dest_binary_dir = os.path.join(translatePath(ADDON.getAddonInfo("profile")).decode('utf-8'), "bin", "%(os)s-%(arch)s" % binary_platform)
        except Exception:
            dest_binary_dir = os.path.join(translatePath(ADDON.getAddonInfo("profile")), "bin", "%(os)s-%(arch)s" % binary_platform)

    binary_path = os.path.join(binary_dir, binary)
    dest_binary_path = os.path.join(dest_binary_dir, binary)
    installed_version = read_current_version(binary_dir)

    log.info("Binary detection. Version: %s, Source: %s, Destination: %s" % (installed_version, binary_path, dest_binary_path))

    if not os.path.exists(binary_path) or not installed_version or version_tuple(ADDON_VERSION) > version_tuple(installed_version):
        try:
            os.makedirs(binary_dir)
        except OSError as e:
            if e.errno != errno.EEXIST:
                raise

        notify("LOCALIZE[30667];;" + "%(os)s-%(arch)s" % binary_platform)
        if not download_github_folder(repo, "%(os)s-%(arch)s" % binary_platform, binary_dir):
            log.error("Unable to download binary to destination path")
            system_information()
            return False, False
        version = download_current_version(repo)
        write_current_version(binary_dir, version)

    if not os.path.exists(binary_path):
        # notify((getLocalizedString(30103) + " %(os)s_%(arch)s" % PLATFORM), time=7000)
        dialog_ok("LOCALIZE[30347];;" + "%(os)s-%(arch)s" % binary_platform)
        system_information()
        try:
            log.info("Source directory (%s):\n%s" % (binary_dir, os.listdir(os.path.join(binary_dir, ".."))))
            log.info("Destination directory (%s):\n%s" % (dest_binary_dir, os.listdir(os.path.join(dest_binary_dir, ".."))))
        except Exception:
            pass
        return False, False

    if os.path.isdir(dest_binary_path):
        log.warning("Destination path is a directory, expected previous binary file, removing...")
        try:
            shutil.rmtree(dest_binary_path)
        except Exception as e:
            log.error("Unable to remove destination path for update: %s" % e)
            system_information()
            return False, False

    if not os.path.exists(dest_binary_path) or not os.path.exists(binary_path) or get_lt2http_checksum(dest_binary_path) != get_lt2http_checksum(binary_path) or not filecmp.cmp(dest_binary_path, binary_path, shallow=True):
        log.info("Updating lt2http daemon...")
        try:
            shutil.rmtree(dest_binary_dir)
        except Exception as e:
            log.error("Unable to remove destination path for update: %s" % e)
        try:
            os.makedirs(dest_binary_dir)
        except OSError as e:
            log.error("Unable to create destination path for update: %s" % e)
        if not os.path.exists(dest_binary_dir):
            log.error("Destination path for update does not exist: %s" % dest_binary_dir)
            system_information()
            return False, False
        try:
            for file_ in os.listdir(binary_dir):
                shutil.copy(os.path.join(binary_dir, file_), os.path.join(dest_binary_dir, file_))
        except Exception as e:
            log.error("Unable to copy to destination path for update: %s" % e)
            system_information()
            return False, False

    # Clean stale files in the directory, as this can cause headaches on
    # Android when they are unreachable
    dest_files = set(os.listdir(dest_binary_dir))
    orig_files = set(os.listdir(binary_dir))
    log.info("Deleting stale files %s" % (dest_files - orig_files))
    for file_ in (dest_files - orig_files):
        path = os.path.join(dest_binary_dir, file_)
        if os.path.isdir(path):
            shutil.rmtree(path)
        else:
            os.remove(path)

    log.info("Binary detection: [ Source: %s, Destination: %s ]" % (binary_path, dest_binary_path))
    return dest_binary_dir, ensure_exec_perms(dest_binary_path)

def clear_fd_inherit_flags():
    # Ensure the spawned lt2http binary doesn't inherit open files from Kodi
    # which can break things like addon updates. [WINDOWS ONLY]
    try:
        from ctypes import windll

        HANDLE_RANGE = six.moves.xrange(0, 65536)
        HANDLE_FLAG_INHERIT = 1
        FILE_TYPE_DISK = 1

        for hd in HANDLE_RANGE:
            if windll.kernel32.GetFileType(hd) == FILE_TYPE_DISK:
                if not windll.kernel32.SetHandleInformation(hd, HANDLE_FLAG_INHERIT, 0):
                    log.error("Error clearing inherit flag, disk file handle %x" % hd)
    except:
        pass

def jsonrpc_enabled(notify=False):
    try:
        s = socket.socket()
        s.connect(('127.0.0.1', 9090))
        s.close()
        log.info("Kodi's JSON-RPC service is available, starting up...")
        del s
        return True
    except Exception as e:
        log.error(repr(e))
        if notify:
            xbmc.executebuiltin("ActivateWindow(ServiceSettings)")
            dialog = xbmcgui.Dialog()
            dialog.ok("Lt2Http", getLocalizedString(30199))
    return False

def start_lt2http(monitor, **kwargs):
    jsonrpc_failures = 0
    while jsonrpc_enabled() is False:
        jsonrpc_failures += 1
        log.warning("Unable to connect to Kodi's JSON-RPC service, retrying...")
        if jsonrpc_failures > 1:
            time.sleep(5)
            if not jsonrpc_enabled(notify=True):
                log.error("Unable to reach Kodi's JSON-RPC service, aborting...")
                return False
            else:
                break
        time.sleep(3)

    lt2http_dir, lt2http_binary = get_lt2http_binary()

    log.info("Binary dir: %s, item: %s " % (lt2http_dir, lt2http_binary))
    if lt2http_dir is False or lt2http_binary is False:
        return False

    stop_running_instance()

    SW_HIDE = 0
    STARTF_USESHOWWINDOW = 1

    args = [lt2http_binary, "--config=%s" % (config_path)]
    kwargs["cwd"] = lt2http_dir

    if binary_platform["os"] == "windows":
        args[0] = getWindowsShortPath(lt2http_binary)
        kwargs["cwd"] = getWindowsShortPath(lt2http_dir)
        si = subprocess.STARTUPINFO()
        si.dwFlags = STARTF_USESHOWWINDOW
        si.wShowWindow = SW_HIDE
        clear_fd_inherit_flags()
        kwargs["startupinfo"] = si
    else:
        env = os.environ.copy()
        env["LD_LIBRARY_PATH"] = "%s:%s" % (lt2http_dir, env.get("LD_LIBRARY_PATH", ""))
        env["GODEBUG"] = "madvdontneed=1"
        kwargs["env"] = env
        kwargs["close_fds"] = True

    wait_counter = 1
    log.debug("Checking for visible")
    while xbmc.getCondVisibility('Window.IsVisible(10140)') or xbmc.getCondVisibility('Window.IsActive(10140)'):
        if wait_counter == 1:
            log.info('Add-on settings currently opened, waiting before starting...')
        if wait_counter > 300:
            break
        time.sleep(1)
        wait_counter += 1

    write_binary_config()

    if ADDON.getSetting("local_force_library") == "true":
        log.info("lt2http: forcing library startup")
    elif hasSubprocess:
        kwargs.update(stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        log.info("lt2http: start args: %s, kw: %s" % (args, kwargs))
        try:
            return subprocess.Popen(args, **kwargs)
        except Exception as e:
            # E.g. Android 10+ does not allow executing binaries from application data folders
            log.error("Unable to start binary, trying library: %s" % e)

    return start_library(monitor, lt2http_dir)

def start_library(monitor, lt2http_dir):
    global lib, last_lib

    if not ctypes_is_supported:
        log.error("lt2http: ctypes is not available, cannot start library")
        return None

    library_path = os.path.join(lt2http_dir, "lt2http.dll" if binary_platform["os"] == "windows" else "lt2http.so")
    try:
        # The log is followed from its start on every run
        open(log_path, 'w').close()

        if last_lib != library_path:
            log.info("lt2http: loading shared library from %s" % library_path)
            lib = cdll.LoadLibrary(library_path)
            lib.startWithLogAndArgs.argtypes = [c_char_p, c_char_p]
            lib.startWithLogAndArgs.restype = c_int
            last_lib = library_path
        else:
            log.info("lt2http: reusing shared library from %s" % library_path)
    except Exception as e:
        log.error("Unable to load library %s: %s" % (library_path, e))
        return None

    library_log_path, library_config_path = log_path, config_path
    if binary_platform["os"] == "windows":
        # The library opens files with narrow (ANSI) paths, short paths keep non-ASCII user folders working
        library_log_path, library_config_path = getWindowsShortPath(log_path), getWindowsShortPath(config_path)
    args = '--config="%s"' % library_config_path

    thread = threading.Thread(target=run_library, args=[monitor, library_log_path, args])
    thread.start()
    return thread

def run_library(monitor, library_log_path, args):
    global last_exit_code

    log.info("lt2http: starting library with args '%s' and log path: %s" % (args, library_log_path))
    last_exit_code = lib.startWithLogAndArgs(library_log_path.encode('utf-8'), args.encode('utf-8'))
    log.info("lt2http: library stopped with code %d" % last_exit_code)

    # Instruct monitor to close and stop waiting for this thread to join
    monitor.close()

def is_client_mode():
    # lt2http runs elsewhere, e.g. a development build in WSL for a Kodi on Windows: the add-on does not start or
    # stop it, it only writes the config file lt2http starts with and sends it the settings changes
    return ADDON.getSetting("local_only_client") == "true"

def stop_running_instance():
    # lt2http has no lockfile: a binary left running by a crashed Kodi keeps the port busy, so it is asked to stop
    url = config.LT2HTTP_HOST
    try:
        urllib_request.urlopen(url + "/shutdown", timeout=1)
    except Exception:
        return

    log.warning("lt2http: stopped an instance left running on %s" % url)
    for _ in range(10):
        time.sleep(1)
        try:
            urllib_request.urlopen(url + "/status", timeout=1)
        except Exception:
            return

def write_binary_config():
    global lt2http_host
    config.init()
    lt2http_host = config.LT2HTTP_HOST
    settings = get_current_settings()
    log.info("Updating settings with: %s" % repr(settings))

    try:
        with open(config_path, 'w') as file:
            file.write(json.dumps(settings))
            file.close()
    except:
        pass
    return ""

def shutdown():
    if is_client_mode():
        return
    try:
        urllib_request.urlopen(lt2http_host + "/shutdown", timeout=1)
    except Exception:
        pass

def update():
    client_mode = is_client_mode()
    if client_mode:
        write_binary_config()
    elif lt2http_host != config.LT2HTTP_HOST:
        # lt2http binds its port only on start: after a clean stop the daemon loop starts it on the new port
        log.info("lt2http: port changed, restarting on %s" % config.LT2HTTP_HOST)
        shutdown()
        return

    settings = get_current_settings()
    if client_mode:
        # Paths of this system, the external lt2http keeps its own
        settings.pop("download_path", None)
        settings.pop("torrents_path", None)

    headers = {'content-type': 'application/json'}
    try:
        requests.post(lt2http_host + "/settings/set", data=json.dumps(settings), headers=headers)
    except Exception as e:
        log.error("Could not update lt2http settings: %s" % e)

def wait_for_abortRequested(proc, monitor):
    monitor.closing.wait()
    log.info("lt2http: exiting daemon")
    try:
        if not isinstance(proc, threading.Thread):
            proc.terminate()
    except OSError:
        pass  # Process already exited, nothing to terminate
    log.info("lt2http: daemon exited")

def lt2http_thread(monitor):
    if is_client_mode():
        write_binary_config()
        log.info("lt2http: client mode, using lt2http running on %s, its config file: %s" % (lt2http_host, config_path))
        return

    restart_count = 0
    max_restart = 3
    last_code = 0

    try:
        # Reuse the service's monitor: this thread blocks in select()/sleep() and never pumps Kodi callbacks,
        # so a Monitor created here would queue every notification forever.
        monitor_abort = monitor
        while not monitor_abort.abortRequested():
            # If we ran out of attempts of last exit code was '-9': we do not try to start it again.
            # So if you kill the binary with '-9': it will not be restarted by this monitor.
            if restart_count > max_restart or last_code == -9:
                if monitor.reboot():
                    log.debug("lt2http: resetting attempts")
                    restart_count = 0
                    last_code = 0
                    monitor.reboot(False)
                else:
                    time.sleep(5)

                continue

            log.info("lt2http: starting")
            proc = start_lt2http(monitor)
            if not proc:
                break

            threading.Thread(target=wait_for_abortRequested, args=[proc, monitor]).start()

            if isinstance(proc, threading.Thread):
                with io.open(log_path, 'r', encoding='utf8', errors='ignore') as log_file:
                    for line in follow(log_file, start=0, delay=0.5, selector=proc.is_alive):
                        log.info(toUtf8(line.rstrip()))
                proc.join()
            elif binary_platform["os"] == "windows":
                while proc.poll() is None:
                    try:
                        log.info(toUtf8(proc.stdout.readline().rstrip()))
                    except TypeError:
                        pass
            else:
                # Kodi hangs on some Android (sigh...) systems when doing a blocking
                # read. We count on the fact that lt2http daemon flushes its log
                # output on \n, creating a pretty clean output
                import fcntl
                import select
                fd = proc.stdout.fileno()
                fl = fcntl.fcntl(fd, fcntl.F_GETFL)
                fcntl.fcntl(fd, fcntl.F_SETFL, fl | os.O_NONBLOCK)
                while proc.poll() is None:
                    try:
                        to_read, _, _ = select.select([proc.stdout], [], [])
                        for ro in to_read:
                            line = ro.readline()
                            if not line:  # write end is closed (b'' on Python 3)
                                break
                            try:
                                log.info(toUtf8(line.rstrip()))
                            except TypeError:
                                pass
                    except IOError:
                        time.sleep(1)  # nothing to read, sleep

            last_code = last_exit_code if isinstance(proc, threading.Thread) else proc.returncode
            # Negative code means killed by signal, e.g. -31 is SIGSYS from Android seccomp
            log.info("lt2http: exited with code %s" % last_code)
            if monitor_abort.abortRequested():
                break
            if last_code == 0 or last_code == -9 or last_code == -1:
                continue

            if last_code == 5:
                restart_count = 0
                notify(getLocalizedString(30332), time=3000)
            else:
                restart_count += 1
                notify(getLocalizedString(30100), time=3000)

            xbmc.executebuiltin("Dialog.Close(all, true)")
            system_information()
            time.sleep(5)

            if restart_count >= max_restart:
                log.debug("lt2http: no attempts left")
                notify(getLocalizedString(30110), time=3000)
                continue

    except Exception as e:
        import traceback
        for line in traceback.format_exc().split("\n"):
            log.error(line)
        notify("%s: %s" % (getLocalizedString(30226), repr(e).encode('utf-8')))
        raise

    log.debug("lt2http: closing")
